begin;
update public.learning_materials set steps='["Buka Belanja Tenun. Pilih kain dan baca nama pembuat, motif, ukuran, bahan, cerita, harga, serta stok.","Masuk sebagai pembeli, tentukan jumlah kain, lalu buka tas belanja. Periksa barang dan alamat pengiriman, lalu pilih Ajukan pesanan.","Buka Tas belanja lalu Pengiriman. Tunggu persetujuan penjual. Setelah disetujui, pilih Lanjutkan pembayaran dan bayar melalui Xendit. Jika ada beberapa penjual, semua penjual harus menyetujui terlebih dahulu. Jangan berikan PIN atau OTP.","Setelah pembayaran terkonfirmasi, pantau diproses, dikirim, dan tiba. Konfirmasi diterima hanya setelah kain benar-benar sampai."]'::jsonb where id=2;
update public.learning_materials set steps=jsonb_set(steps,'{3}','"Buka Pesanan masuk, periksa ketersediaan kain dan pilih Setujui pesanan atau Tolak pesanan. Penolakan membatalkan seluruh pesanan dan mengembalikan stok. Setelah semua penjual menyetujui, tunggu pembayaran terkonfirmasi sebelum memproses, mengirim, dan menandai barang tiba."'::jsonb) where id=3;
update public.learning_materials set steps='["Buka Pesanan masuk. Pesanan baru menunggu persetujuan penjual. Admin dapat membantu menyetujui atau menolak seluruh pesanan setelah memeriksa ketersediaan dengan penjual.","Tunggu pembayaran Xendit terkonfirmasi otomatis, lalu pilih Proses & kemas pesanan. Cocokkan barang, jumlah, pembuat, alamat, dan kontak pembeli.","Sesudah diserahkan kepada pengiriman, pilih Tandai dikirim. Tandai tiba hanya setelah ada kepastian barang sampai. Pembeli mengonfirmasi penerimaan.","Jika pembayaran belum terkonfirmasi atau terjadi masalah, periksa dashboard Xendit dan hubungi pembeli melalui kontak pesanan. Jangan mengubah pembayaran menjadi lunas tanpa verifikasi."]'::jsonb where id=5;
commit;
